steps.input:
jq query: kubectl get deployments | jq ''.items[] | select(.metadata.namespace=="ledger") | {name:.metadata.name, version:.metadata.labels["app.kubernetes.io/version"]?, images: [.spec.template.spec.containers[].image], replicas:.status.replicas, available:.status.availableReplicas} ''
{
                    "kind": "deployments",
                    "jq_expr": ".items[] | select(.metadata.namespace==\"ledger\") | {name:.metadata.name, version:.metadata.labels[\"app.kubernetes.io/version\"]?, images: [.spec.template.spec.containers[].image], replicas:.status.replicas, available:.status.availableReplicas} "
                }

jq query: kubectl get replicasets | jq ''.items[] | select(.metadata.namespace=="ledger") | {name:.metadata.name, owner: (.metadata.ownerReferences[0].name // ""), replicas:.status.replicas, available:.status.availableReplicas, images: [.spec.template.spec.containers[].image] }''
{
                    "kind": "replicasets",
                    "jq_expr": ".items[] | select(.metadata.namespace==\"ledger\") | {name:.metadata.name, owner: (.metadata.ownerReferences[0].name // \"\"), replicas:.status.replicas, available:.status.availableReplicas, images: [.spec.template.spec.containers[].image] }"
                }

jq query: kubectl get pods | jq ''.items[] | select(.metadata.namespace=="ledger" and .metadata.name | test("ledger-api-866db84748-.*")) | {name:.metadata.name, node:.spec.nodeName, podIP:.status.podIP, readinessProbe:.spec.containers[0].readinessProbe }''
{
                    "kind": "pods",
                    "jq_expr": ".items[] | select(.metadata.namespace==\"ledger\" and .metadata.name | test(\"ledger-api-866db84748-.*\")) | {name:.metadata.name, node:.spec.nodeName, podIP:.status.podIP, readinessProbe:.spec.containers[0].readinessProbe }"
                }

